  if(view==='source'){const sourceEpoch=epoch,isCurrent=()=>epoch===sourceEpoch&&!detail.hidden&&view==='source';void sourceReader.loadPassages(getProject(),r,detail,isCurrent);void sourceReader.load(getProject(),detail,isCurrent,{role:r.role});}
